"""Synthetic Hangul dataset generated by rendering fonts with random,
handwriting-like distortions. This lets us train without a labeled
handwriting dataset on disk.
"""

import random

import numpy as np
import torch
from PIL import Image, ImageDraw, ImageFont
from scipy.ndimage import gaussian_filter, grey_dilation, grey_erosion, map_coordinates
from torch.utils.data import Dataset

from .charset import CHARSET

# 시스템에 설치된 한글 폰트 후보 목록 (스타일 다양성을 위해 여러 종류 사용)
FONT_CANDIDATES = [
    r"C:\Windows\Fonts\malgun.ttf",
    r"C:\Windows\Fonts\malgunbd.ttf",
    r"C:\Windows\Fonts\malgunsl.ttf",
    r"C:\Windows\Fonts\batang.ttc",
    r"C:\Windows\Fonts\gulim.ttc",
    r"C:\Windows\Fonts\HANBatang.ttf",
    r"C:\Windows\Fonts\HANBatangB.ttf",
    r"C:\Windows\Fonts\HANDotum.ttf",
    r"C:\Windows\Fonts\HANDotumB.ttf",
    r"C:\Windows\Fonts\KoPubBatangMedium.ttf",
    r"C:\Windows\Fonts\KoPubBatangBold.ttf",
    r"C:\Windows\Fonts\KoPubDotumMedium.ttf",
    r"C:\Windows\Fonts\KoPubDotumBold.ttf",
    r"C:\Windows\Fonts\UnBatang.ttf",
    r"C:\Windows\Fonts\UnDotum.ttf",
    r"C:\Windows\Fonts\NGULIM.TTF",
]

RENDER_SIZE = 128  # 렌더링 및 왜곡 처리를 진행할 중간 해상도
MODEL_SIZE = 64    # 모델에 최종적으로 입력되는 이미지 크기


def _load_working_fonts():
    """실제로 로드 가능한 폰트 경로만 걸러서 반환한다."""
    working = []
    for path in FONT_CANDIDATES:
        try:
            ImageFont.truetype(path, 40)
            working.append(path)
        except OSError:
            print(f"[dataset] 폰트를 불러올 수 없어 건너뜁니다: {path}")
    if not working:
        raise RuntimeError("사용 가능한 한글 폰트를 하나도 찾지 못했습니다.")
    return working


FONT_PATHS = _load_working_fonts()


def _draw_centered_char(char: str, font_path: str, font_size: int) -> Image.Image:
    """흰 배경(255) 위에 검은 글자(0)를 중앙 정렬해서 그린다."""
    img = Image.new("L", (RENDER_SIZE, RENDER_SIZE), color=255)
    draw = ImageDraw.Draw(img)
    font = ImageFont.truetype(font_path, font_size)
    bbox = draw.textbbox((0, 0), char, font=font)
    w, h = bbox[2] - bbox[0], bbox[3] - bbox[1]
    x = (RENDER_SIZE - w) / 2 - bbox[0]
    y = (RENDER_SIZE - h) / 2 - bbox[1]
    draw.text((x, y), char, font=font, fill=0)
    return img


def _disk_footprint(radius: int) -> np.ndarray:
    """반경 radius의 원형 구조 요소를 만든다 (마우스 펜의 둥근 획을 흉내내기 위함)."""
    y, x = np.ogrid[-radius:radius + 1, -radius:radius + 1]
    return (x ** 2 + y ** 2) <= radius ** 2 + radius


def _elastic_distort(arr: np.ndarray, rng: random.Random, alpha: float, sigma: float) -> np.ndarray:
    """탄성 왜곡을 적용해 손으로 쓴 듯한 불규칙함을 흉내낸다."""
    seed = rng.randint(0, 2**31 - 1)
    local_state = np.random.RandomState(seed)
    shape = arr.shape
    dx = gaussian_filter((local_state.rand(*shape) * 2 - 1), sigma) * alpha
    dy = gaussian_filter((local_state.rand(*shape) * 2 - 1), sigma) * alpha
    y, x = np.meshgrid(np.arange(shape[0]), np.arange(shape[1]), indexing="ij")
    indices = (np.reshape(y + dy, (-1, 1)), np.reshape(x + dx, (-1, 1)))
    distorted = map_coordinates(arr, indices, order=1, mode="constant", cval=255.0)
    return distorted.reshape(shape)


def render_char_image(char: str, rng: random.Random) -> torch.Tensor:
    """하나의 글자를 무작위 폰트/왜곡으로 렌더링해 모델 입력 텐서로 변환한다.

    실제 마우스 손글씨는 폰트 글자보다 획이 훨씬 두껍고 둥글며 구조 비율도
    들쭉날쭉하다. 이 차이를 줄이기 위해 원형 팽창(둥근 펜 두께)과 강한 탄성
    왜곡을 기본적으로 적용한다.
    """
    font_path = rng.choice(FONT_PATHS)
    font_size = rng.randint(int(RENDER_SIZE * 0.5), int(RENDER_SIZE * 0.78))
    img = _draw_centered_char(char, font_path, font_size)

    # 기울임(shear)으로 삐뚤어진 손글씨 느낌을 추가 (너무 크면 글자가 무너지므로 약하게)
    shear = rng.uniform(-0.12, 0.12)
    img = img.transform(
        (RENDER_SIZE, RENDER_SIZE), Image.AFFINE,
        (1, shear, -shear * RENDER_SIZE / 2, 0, 1, 0),
        resample=Image.BICUBIC, fillcolor=255,
    )

    # 회전으로 손글씨의 기울어짐을 흉내낸다
    angle = rng.uniform(-13, 13)
    img = img.rotate(angle, resample=Image.BICUBIC, fillcolor=255)

    arr = np.asarray(img, dtype=np.float32)

    # 마우스로 그린 획은 폰트보다 두꺼운 경우가 많으므로 두껍게 만드는 쪽에
    # 비중을 두되, 반경을 너무 키우면 글자가 뭉개지므로 적당히 제한한다.
    thickness_roll = rng.random()
    if thickness_roll < 0.55:
        radius = rng.choice([1, 1, 2, 2, 3])
        arr = grey_erosion(arr, footprint=_disk_footprint(radius))  # 획이 두꺼워짐
    elif thickness_roll < 0.7:
        radius = 1
        arr = grey_dilation(arr, footprint=_disk_footprint(radius))  # 획이 얇아짐

    # 탄성 왜곡으로 손떨림/불균일한 비율 같은 구조적 변형을 추가 (원래보다 살짝 강하게)
    alpha = rng.uniform(5.0, 12.0)
    sigma = rng.uniform(4.0, 6.0)
    arr = _elastic_distort(arr, rng, alpha, sigma)

    # 약간의 블러로 마우스 잉크의 뭉개진 가장자리를 흉내낸다
    if rng.random() < 0.4:
        arr = gaussian_filter(arr, sigma=rng.uniform(0.3, 0.8))

    # 약간의 가우시안 노이즈 추가
    noise_sigma = rng.uniform(0.0, 8.0)
    arr = arr + np.random.RandomState(rng.randint(0, 2**31 - 1)).normal(0, noise_sigma, arr.shape)
    arr = np.clip(arr, 0, 255)

    out_img = Image.fromarray(arr.astype(np.uint8)).resize((MODEL_SIZE, MODEL_SIZE), Image.LANCZOS)
    tensor = torch.from_numpy(np.asarray(out_img, dtype=np.float32) / 255.0)
    tensor = 1.0 - tensor  # 배경 0, 잉크 1 이 되도록 반전
    return tensor.unsqueeze(0)  # (1, H, W)


class HangulSyntheticDataset(Dataset):
    """매번 접근할 때마다 새롭게 왜곡된 이미지를 생성하는 데이터셋.

    train=True 이면 매번 완전히 무작위 이미지를 생성해 무한한 증강 효과를 준다.
    train=False 이면 인덱스 기반 고정 시드를 사용해 항상 같은 검증용 이미지를 만든다.
    """

    def __init__(self, samples_per_class: int, train: bool = True):
        self.samples_per_class = samples_per_class
        self.train = train
        self.charset = CHARSET

    def __len__(self):
        return len(self.charset) * self.samples_per_class

    def __getitem__(self, idx):
        label = idx % len(self.charset)
        char = self.charset[label]
        if self.train:
            rng = random.Random()  # 매 호출마다 다른 무작위성
        else:
            rng = random.Random(idx)  # 검증셋은 항상 동일하게 재현
        image = render_char_image(char, rng)
        return image, label
